+    mxArray *capsule_mat = mxCreateNumericMatrix(1, 1, mxINT64_CLASS, mxREAL);
+    l_ptr = mxGetData(capsule_mat);
+    l_ptr[0] = (long long) acados_ocp_capsule;
+    mxSetField(plhs[0], 0, "capsule", capsule_mat);
+
