+    void *nlp_opts = {{ model.name }}_acados_get_nlp_opts(acados_ocp_capsule);
+
+    // initial condition
+    int idxbx0[NBX0];
+    {%- for i in range(end=dims.nbx_0) %}
+    idxbx0[{{ i }}] = {{ constraints.idxbx_0[i] }};
