+
+{%- if dims.np > 0 %}
+input_note = strcat(input_note, num2str(i_in), ') parameters, size [{{ dims.np }}]\n ');
+i_in = i_in + 1;
+{%- endif %}
+
+
+fprintf(input_note)
+
+disp(' ')
+
+output_note = strcat('Outputs are:\n', ...
+                '1) x1 - simulated state, size [{{ dims.nx }}]\n');
+
+fprintf(output_note)

